use std::{io::Write,process::{Command,Stdio}};
fn corpus()->serde_json::Value{serde_json::from_str(include_str!("../../🧫️fixtures/🪶️sqlite/🔣️.json")).unwrap()}
fn owned(case:&serde_json::Value)->ChartSnapshot{ChartSnapshot{chart:DslValue::from(&case["snapshot"]["chart"])}}
fn exact(actual:&DslValue,expected:&DslValue){match(actual,expected){
 (DslValue::Number(Number::UInt(a)),DslValue::Number(Number::UInt(b)))=>assert_eq!(a,b),
 (DslValue::Number(Number::Int(a)),DslValue::Number(Number::Int(b)))=>assert_eq!(a,b),
 (DslValue::Number(Number::Float(a)),DslValue::Number(Number::Float(b)))=>assert_eq!(a.to_bits(),b.to_bits()),
 (DslValue::Array(a),DslValue::Array(b))=>{assert_eq!(a.len(),b.len());for(a,b)in a.iter().zip(b){exact(a,b);}},
 (DslValue::Object(a),DslValue::Object(b))=>{assert_eq!(a.len(),b.len());for(key,value)in b{let matches:Vec<_>=a.iter().filter(|(name,_)|name==key).collect();assert_eq!(matches.len(),1,"duplicate or missing domain member {key}");exact(&matches[0].1,value);}},
 (DslValue::Null,DslValue::Null)=>{},(DslValue::Bool(a),DslValue::Bool(b))=>assert_eq!(a,b),(DslValue::String(a),DslValue::String(b))=>assert_eq!(a,b),
 _=>panic!("native Chart value differs: actual={actual:?}; expected={expected:?}")
}}
fn project(snapshot:&ChartSnapshot)->protocol::sqlite_snapshot::SqliteDatabase{snapshot.to_sqlite_database(&mut SqliteSnapshotControl::new(&mut |_|true,Default::default())).unwrap()}
fn file(snapshot:&ChartSnapshot)->Vec<u8>{export_sqlite_database(&project(snapshot),Default::default(),&mut |_|true).unwrap()}
fn independent(script:&str,bytes:&[u8])->Vec<u8>{let mut child=Command::new("bun").args(["-e",script]).stdin(Stdio::piped()).stdout(Stdio::piped()).stderr(Stdio::piped()).spawn().unwrap();let write=child.stdin.take().unwrap().write_all(bytes);let result=child.wait_with_output().unwrap();assert!(write.is_ok()&&result.status.success(),"independent Chart oracle write={write:?}; stderr={}",String::from_utf8_lossy(&result.stderr));result.stdout}
#[test]
fn sqlite_snapshot_chart_full_domain_and_authored_default_are_independently_readable(){
 let c=corpus();for case in c["cases"].as_array().unwrap(){let expected=owned(case);let bytes=file(&expected);assert_eq!(&bytes[..16],b"SQLite format 3\0");let database=import_sqlite_database(&bytes,Default::default(),&mut |_|true).unwrap();let actual=ChartSnapshot::from_sqlite_database(&database,&mut SqliteSnapshotControl::new(&mut |_|true,Default::default())).unwrap();exact(&actual.chart,&expected.chart);let script=r#"import{Database}from'bun:sqlite';const d=Database.deserialize(new Uint8Array(await Bun.stdin.arrayBuffer()));if(d.query('PRAGMA integrity_check').get().integrity_check!=='ok'||d.query('PRAGMA foreign_key_check').all().length)throw Error('integrity');console.log(JSON.stringify(d.query('SELECT width,height,language FROM chart_document').get()));d.close();"#;let row:serde_json::Value=serde_json::from_slice(&independent(script,&bytes)).unwrap();assert_eq!(row["width"],case["snapshot"]["chart"]["width"]);assert_eq!(row["height"],case["snapshot"]["chart"]["height"]);assert_eq!(row["language"],case["snapshot"]["chart"]["language"]);}
 exact(&ChartSnapshot::default().chart,&owned(&c["cases"][2]).chart);
 eprintln!("[DEBUG] Chart four neutral states preserve complete fields, optional presence and actual default through independent SQLite");
}
#[test]
fn sqlite_snapshot_chart_native_numeric_variants_and_float_words_are_exact(){
 let row=DslValue::object([("wide".into(),DslValue::uint(u64::MAX)),("signed".into(),DslValue::int(i64::MIN)),("positive_signed".into(),DslValue::int(7)),("negative_zero".into(),DslValue::float(-0.0)),("float_integer".into(),DslValue::float(7.0))]);
 let table=DslValue::object([("name".into(),DslValue::String("exact".into())),("columns".into(),DslValue::Array(["wide","signed","positive_signed","negative_zero","float_integer"].map(|key|DslValue::String(key.into())).to_vec())),("rows".into(),DslValue::Array(vec![row]))]);
 let expected=ChartSnapshot{chart:DslValue::object([("width".into(),DslValue::uint(80)),("height".into(),DslValue::uint(40)),("language".into(),DslValue::String("en".into())),("tables".into(),DslValue::Array(vec![table])),("layers".into(),DslValue::Array(Vec::new()))])};
 let database=project(&expected);let actual=ChartSnapshot::from_sqlite_database(&database,&mut SqliteSnapshotControl::new(&mut |_|true,Default::default())).unwrap();exact(&actual.chart,&expected.chart);
 for encoding in[SnapshotEncoding::Binary,SnapshotEncoding::Text]{let native=expected.encode_sqlite_snapshot_native(encoding,&mut SqliteSnapshotControl::new(&mut |_|true,Default::default())).unwrap();let actual=ChartSnapshot::decode_sqlite_snapshot_native(&native,&mut SqliteSnapshotControl::new(&mut |_|true,Default::default())).unwrap();exact(&actual.chart,&expected.chart);}
 eprintln!("[DEBUG] Chart Native UInt64, Int64, positive Int, negative zero and integral Float preserve exact variant and bits");
}
#[test]
fn sqlite_snapshot_chart_independent_queries_and_scalar_edit_preserve_full_owner(){
 let c=corpus();let expected=owned(&c["cases"][0]);let bytes=file(&expected);let script=r#"import{Database}from'bun:sqlite';const d=Database.deserialize(new Uint8Array(await Bun.stdin.arrayBuffer()));console.log(JSON.stringify({columns:d.query('SELECT ordinal,name FROM chart_column ORDER BY ordinal').all(),layers:d.query('SELECT ordinal,mark,data FROM chart_layer ORDER BY ordinal').all(),cells:d.query('SELECT value_kind,COUNT(*) AS count FROM chart_cell GROUP BY value_kind ORDER BY value_kind').all(),tables:d.query("SELECT name FROM sqlite_schema WHERE type='table'").all().map(r=>r.name)}));d.close();"#;let seen:serde_json::Value=serde_json::from_slice(&independent(script,&bytes)).unwrap();assert_eq!(seen["columns"],c["queries"][1]["rows"]);assert_eq!(seen["layers"],c["queries"][2]["rows"]);assert_eq!(seen["cells"],c["queries"][3]["rows"]);for name in c["requiredTables"].as_array().unwrap(){assert!(seen["tables"].as_array().unwrap().contains(name));}
 let script=r#"import{Database}from'bun:sqlite';const d=Database.deserialize(new Uint8Array(await Bun.stdin.arrayBuffer()));d.exec('UPDATE chart_document SET width=125');await Bun.write(Bun.stdout,d.serialize());d.close();"#;let edited=independent(script,&bytes);let actual=ChartSnapshot::from_sqlite_database(&import_sqlite_database(&edited,Default::default(),&mut |_|true).unwrap(),&mut SqliteSnapshotControl::new(&mut |_|true,Default::default())).unwrap();let mut expected=expected;if let DslValue::Object(fields)=&mut expected.chart{fields.iter_mut().find(|(key,_)|key=="width").unwrap().1=DslValue::float(125.0);}exact(&actual.chart,&expected.chart);
 eprintln!("[DEBUG] Chart independent domain SQL, duplicate column occurrences, typed cells and scalar edit bind the full owner");
}
#[test]
fn sqlite_snapshot_chart_surrogate_renumber_and_corrupt_ownership_are_distinct(){
 let c=corpus();let expected=owned(&c["cases"][0]);let bytes=file(&expected);let script=r#"import{Database}from'bun:sqlite';const d=Database.deserialize(new Uint8Array(await Bun.stdin.arrayBuffer()));d.exec('PRAGMA foreign_keys=OFF');for(const{name}of d.query("SELECT name FROM sqlite_schema WHERE type='table'").all()){const key=d.query('PRAGMA table_info('+name+')').all().find(c=>c.pk===1).name;const links=d.query('PRAGMA foreign_key_list('+name+')').all();d.exec('UPDATE '+name+' SET '+[key+'='+key+'+1000',...links.filter(l=>l.from!==key).map(l=>l.from+'='+l.from+'+1000')].join(','));}if(d.query('PRAGMA foreign_key_check').all().length)throw Error('renumbered ownership');await Bun.write(Bun.stdout,d.serialize());d.close();"#;let changed=independent(script,&bytes);let actual=ChartSnapshot::from_sqlite_database(&import_sqlite_database(&changed,Default::default(),&mut |_|true).unwrap(),&mut SqliteSnapshotControl::new(&mut |_|true,Default::default())).unwrap();exact(&actual.chart,&expected.chart);
 for sql in c["corruptions"].as_array().unwrap(){let script=format!("import{{Database}}from'bun:sqlite';const d=Database.deserialize(new Uint8Array(await Bun.stdin.arrayBuffer()));d.exec('PRAGMA ignore_check_constraints=ON');d.exec({});await Bun.write(Bun.stdout,d.serialize());d.close();",sql);let changed=independent(&script,&bytes);let database=import_sqlite_database(&changed,Default::default(),&mut |_|true).unwrap();assert!(ChartSnapshot::from_sqlite_database(&database,&mut SqliteSnapshotControl::new(&mut |_|true,Default::default())).is_err());}
 eprintln!("[DEBUG] Chart positive SQL surrogate renumber preserves ownership; orphan and noncontiguous order refuse");
}
#[semio_framework_async_macros::async_test]
async fn sqlite_snapshot_chart_ordinary_plugin_installs_typed_file_and_native_text_pack_routes(){
 use protocol::io::{ArtifactDialect,io_mechanism::{io_export_sqlite_snapshot,io_import_sqlite_snapshot,io_route,io_run_with_snapshot_control,native_snapshot_sqlite_schema}};use protocol::io_schema::{IoPayload,IoFidelity,SQLITE_SNAPSHOT};
 crate::print_plugin().expect("ordinary Print initialization must install Chart's actual native SQLite owner");let c=corpus();let dialect=ArtifactDialect{artifact_kind:c["artifactKind"].as_str().unwrap().into(),standard:c["dialect"]["standard"].as_str().unwrap().into(),subset:c["dialect"]["subset"].as_str().unwrap().into()};assert_eq!(native_snapshot_sqlite_schema(&dialect).unwrap(),ChartSnapshot::SQLITE_SCHEMA);let sqlite=ArtifactDialect::from(SQLITE_SNAPSHOT);let export=io_route(&dialect,&sqlite,1).await.unwrap().value;let import=io_route(&sqlite,&dialect,1).await.unwrap().value;assert_eq!(export.fidelity,IoFidelity::Exact);assert_eq!(import.fidelity,IoFidelity::Exact);
 for case in c["cases"].as_array().unwrap(){let expected=owned(case);for encoding in[SnapshotEncoding::Binary,SnapshotEncoding::Text]{let bytes=io_export_sqlite_snapshot(&dialect,&expected,encoding,Default::default(),&mut |_|true).await.unwrap().value;let actual=io_import_sqlite_snapshot::<ChartSnapshot>(&dialect,&bytes,Default::default(),&mut |_|true).await.unwrap().value;exact(&actual.chart,&expected.chart);let payload=expected.encode_sqlite_snapshot_native(encoding,&mut SqliteSnapshotControl::new(&mut |_|true,Default::default())).unwrap();let mut phases=Vec::new();let file=io_run_with_snapshot_control(&export,payload,Default::default(),&mut |event|{phases.push(event.phase);true}).await.unwrap().value;assert!(phases.contains(&SqliteSnapshotPhase::ProjectSnapshot));assert!(phases.contains(&SqliteSnapshotPhase::WritePages));let IoPayload::Binary(bytes)=file else{panic!("SQLite endpoint must return physical bytes")};let native=io_run_with_snapshot_control(&import,IoPayload::Binary(bytes),Default::default(),&mut |_|true).await.unwrap().value;let actual=ChartSnapshot::decode_sqlite_snapshot_native(&native,&mut SqliteSnapshotControl::new(&mut |_|true,Default::default())).unwrap();exact(&actual.chart,&expected.chart);}}
 eprintln!("[DEBUG] Chart ordinary plugin actual schema/type registration, typed SQLite file and both native public I/O routes preserve all four owners");
}
#[test]
fn sqlite_snapshot_chart_control_and_closed_domain_refusals_are_real(){
 let expected=owned(&corpus()["cases"][0]);let database=project(&expected);assert!(expected.to_sqlite_database(&mut SqliteSnapshotControl::new(&mut |_|false,Default::default())).is_err());assert!(ChartSnapshot::from_sqlite_database(&database,&mut SqliteSnapshotControl::new(&mut |_|false,Default::default())).is_err());let zero=SqliteDatabaseLimits{max_allocation_bytes:0,..Default::default()};assert!(expected.to_sqlite_database(&mut SqliteSnapshotControl::new(&mut |_|true,zero)).is_err());assert!(ChartSnapshot::from_sqlite_database(&database,&mut SqliteSnapshotControl::new(&mut |_|true,zero)).is_err());for encoding in[SnapshotEncoding::Binary,SnapshotEncoding::Text]{assert!(expected.encode_sqlite_snapshot_native(encoding,&mut SqliteSnapshotControl::new(&mut |_|false,Default::default())).is_err());assert!(expected.encode_sqlite_snapshot_native(encoding,&mut SqliteSnapshotControl::new(&mut |_|true,zero)).is_err());let native=expected.encode_sqlite_snapshot_native(encoding,&mut SqliteSnapshotControl::new(&mut |_|true,Default::default())).unwrap();assert!(ChartSnapshot::decode_sqlite_snapshot_native(&native,&mut SqliteSnapshotControl::new(&mut |_|false,Default::default())).is_err());assert!(ChartSnapshot::decode_sqlite_snapshot_native(&native,&mut SqliteSnapshotControl::new(&mut |_|true,zero)).is_err());}
 let mut unknown=expected.clone();if let DslValue::Object(fields)=&mut unknown.chart{fields.push(("unowned".into(),DslValue::Bool(true)));}assert!(unknown.to_sqlite_database(&mut SqliteSnapshotControl::new(&mut |_|true,Default::default())).is_err());let mut duplicate=expected;if let DslValue::Object(fields)=&mut duplicate.chart{fields.push(("width".into(),DslValue::uint(1)));}assert!(duplicate.to_sqlite_database(&mut SqliteSnapshotControl::new(&mut |_|true,Default::default())).is_err());
 eprintln!("[DEBUG] Chart real projection, reconstruction, native cancellation, zero ownership and unknown/duplicate domain members refuse");
}

/// 🚫️ The Native provider follows the same closed scalar refusal corpus as Source and AJV.
#[test]
fn sqlite_snapshot_chart_known_scalar_admission_refuses_norm_invalid_values(){let c=corpus();for case in c["invalidCases"].as_array().unwrap(){let mut chart=c["cases"][0]["snapshot"]["chart"].clone();let path=case["path"].as_array().unwrap();let mut parent=&mut chart;for segment in &path[..path.len()-1]{parent=if let Some(index)=segment.as_u64(){&mut parent[index as usize]}else{&mut parent[segment.as_str().unwrap()]};}let last=path.last().unwrap().as_str().unwrap();parent[last]=case["value"].clone();let snapshot=ChartSnapshot{chart:DslValue::from(chart)};assert!(snapshot.to_sqlite_database(&mut SqliteSnapshotControl::new(&mut |_|true,Default::default())).is_err(),"known scalar must refuse: {}",case["id"]);}eprintln!("[DEBUG] Chart Native eighteen known scalar admission cases follow the closed neutral normative refusal corpus");}
